raw:
{
  "spells": [
    {
      "id": "spell_summon_07",
      "theory": "召唤术以魔力在空气中勾勒出风雀的轮廓，再以契约印记将投影锚定在已知短途路线上。风雀并非实体生灵，而是由风元素回应召唤者意志形成的临时形体，能抓握轻质纸签并沿直线或缓弯路径飞行。投影与召唤者之间维持着一根极细的魔力丝线，丝线断裂则风雀即刻消散，纸签随之坠落。路径必须提前在脑海中清晰勾勒，模糊的路线会让风雀中途迷失。",
      "casting": "左手拇指与食指捏住纸签一角，右手在空中画出一道螺旋上升的符文，同时低声念出契约短句。符文闭合后松开纸签，风雀投影便从符文中心展翅而出，衔住纸签沿既定路线飞去。",
      "failure": "符文未闭合时风雀只现出半个翅膀便溃散，纸签被风吹落在地。路径勾勒不清则风雀飞到半途突然悬停，原地打转几圈后消失，纸签从空中飘落。魔力丝线若被外力扯断，风雀当场碎裂成乱流，纸签可能被卷到偏离方向的位置。",
      "counters": [
        "在风雀必经路径上张开细网或悬挂布幔，投影撞上后魔力丝线会提前崩解。",
        "用另一道风系法术扰乱局部气流，使风雀失去稳定升力而坠落。"
      ],
      "socialConsequences": "河谷乡约视风雀传签为便捷的信使替代，只要不飞越他人宅院上空便不干涉。中陆城市的公会文书房欢迎此术，认为它比人力跑腿更少出错，但要求召唤者对纸签内容负责，若传递欺诈文书则追究召唤者。琥珀海岸的船主乐于用它向岸上传递到港消息，港务则提醒不得在货舱密集区施放，以免风雀撞上桅索坠落引发混乱。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学阶段风雀飞行轨迹偶有偏移，纸签可能落在目标几步之外。",
        "熟练度提升后风雀能稳定沿缓弯路径飞行，纸签落点更为准确。",
        "进一步掌握可使风雀在微风中保持航向，减少中途悬停的次数。",
        "高熟练度下风雀能精确降落在指定平面，仍只沿已知短路线飞行。"
      ]
    },
    {
      "id": "spell_summon_08",
      "theory": "潮鳍卫灵以魔力在浅水中凝聚出一尾鱼形投影，其躯体由水元素与契约印记共同维持。投影只在液体中活动，离水即溃散为普通水滴。它能环绕指定水域巡游，对靠近的活物发出震动警告，但无法离开水面追击或搬运重物。召唤者需在水中预先画出契约环，环的大小决定卫灵的活动范围。投影与召唤者之间通过水体传递感知，召唤者能察觉卫灵发出的震动，但无法通过它视物或听声。",
      "casting": "蹲在浅水边，右手食指在水中画出一个闭合圆环，同时左手轻拍水面三下。圆环成形后投入魔力，水中便升起一尾半透明的鱼形投影，开始沿环线巡游。",
      "failure": "圆环未闭合时水面只冒出一串气泡，卫灵无法成形。水中杂质过多会使投影刚出现就散成浑浊水雾，需要等待水体澄清后重试。若召唤者与卫灵之间的水体被隔断，投影会停在断口处反复撞击，最终自行消散。",
      "counters": [
        "在卫灵巡游的水域撒入细沙或泥浆，浑浊水体令投影难以维持形体。",
        "用容器舀走部分水体，使水位低于契约环下沿，投影便失去依托而溃散。"
      ],
      "socialConsequences": "河谷渔户常请人施放潮鳍卫灵看守夜间泊船，乡约允许在自家泊位使用，但若投影越界进入他人渔区则视为侵占。中陆城市的公会记录此类召唤需报备水域范围，避免与市政排水或渡船航线冲突。琥珀海岸的港务对货栈水池使用卫灵持宽容态度，但若投影惊扰装卸工人或误报货损，港务会追究召唤者的责任并要求赔偿误工。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时卫灵巡游范围略小于契约环，边缘常有遗漏。",
        "熟练度提升后卫灵能均匀覆盖环内水域，震动警告更为及时。",
        "进一步掌握可让卫灵在缓流中保持稳定巡游，减少随波漂移。",
        "高熟练度下卫灵能精确沿环线往返，仍只在水中活动且不离开设定范围。"
      ]
    },
    {
      "id": "spell_summon_09",
      "theory": "契约续供以额外魔力与约定供品为代价，延长已有合法召唤的存续时间。施术者需触摸原召唤的契约印记，将新魔力注入其中，同时献上供品作为维持投影的燃料。供品被魔力分解为细碎光点，融入投影体内，使其形体重新稳固。若原召唤并非由施术者本人建立，则续供需要原召唤者的印记残留作为中介，否则新魔力无法对接。续供不改变原召唤的能力或范围，只延长其存在时间。",
      "casting": "单膝跪在召唤物旁，右手掌按住其契约印记，左手将供品置于印记上方。闭眼送入魔力，待供品化为光点被印记吸收后，续供便完成。",
      "failure": "供品未被魔力分解时会原样滚落，续供失败且魔力白费。若印记已被磨损或篡改，新魔力注入后可能反冲，使召唤物提前消散并留下一阵刺鼻气味。续供过程中若召唤物被外力驱散，供品光点会四散消失，无法回收。",
      "counters": [
        "用湿布覆盖契约印记，阻断魔力注入通道，使续供无法完成。",
        "在供品上涂抹盐粒，盐会干扰魔力分解过程，令供品无法转化为光点。"
      ],
      "socialConsequences": "河谷乡约认可续供为正常维护手段，只要供品来源合法且不涉及他人财物。中陆城市的公会要求续供记录在案，以便追踪长期召唤物的用途，若续供用于维持未经许可的召唤则连带追责。琥珀海岸的港务允许对合法召唤的货栈守卫或水道巡查投影续供，但若续供消耗的供品属于他人寄存货物，港务会按货损条例追究召唤者。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学阶段续供后投影存续时间略短于标准时长，形体偶有闪烁。",
        "熟练度提升后续供能稳定延长投影存续时间，形体不再闪烁。",
        "进一步掌握可减少供品消耗，仍只延长原召唤的存续时间。",
        "高熟练度下续供几乎不产生魔力浪费，投影存续时间达到该术上限。"
      ]
    }
  ]
}
